```python
# Initialize the inventory dictionary
inventory = {}

def add_book(book_id, title, author, isbn):
    """Add a book to the inventory with the given ID, title, author, and ISBN."""
    if book_id in inventory:
        print(f"Book with ID {book_id} already exists. Cannot add a duplicate book.")
        return

    inventory[book_id] = {
        "title": title,
        "author": author,
        "isbn": isbn,
    }
    print(f"New book added with ID {book_id}: {title} by {author} (ISBN: {isbn})")

def remove_book(book_id):
    """Remove a book from the inventory with the given ID."""
    if book_id not in inventory:
        print(f"Book with ID {book_id} not found in the inventory.")
        return

    del inventory[book_id]
    print(f"Book with ID {book_id} removed from the inventory.")

def search_book(book_id):
    """Search for a book in the inventory with the given ID."""
    if book_id not in inventory:
        print(f"Book with ID {book_id} not found in the inventory.")
        return

    print(f"Book with ID {book_id} found in the inventory: {inventory[book_id]['title']} by {inventory[book_id]['author']} (ISBN: {inventory[book_id]['isbn']})")

# Main program loop
while True:
    user_input = input("Enter 'add' to add a book, 'remove' to remove a book, 'search' to search for a book, or 'quit' to exit: ").lower()

    if user_input == "add":
        book_id = input("Enter the book ID: ")
        title = input("Enter the title: ")
        author = input("Enter the author: ")
        isbn = input("Enter the ISBN: ")
        add_book(book_id, title, author, isbn)

    elif user_input == "remove":
        book_id = input("Enter the book ID to remove: ")
        remove_book(book_id)

    elif user_input == "search":
        book_id = input("Enter the book ID to search: ")
        search_book(book_id)

    elif user_input == "quit":
        print("Goodbye!")
        break

    else:
        print("Invalid input. Please try again.")
```
